touchComponent.event:
if (not game.tutorialActive() and game.popUpLevel() <= 1) then if(manager:getQueuedContext() ~= "") then manager:setReserveState(manager:getQueuedContext()) else manager:setReserveState(manager:getContext()) end manager:setContext("USER_PROFILE_MENU")
element:setColorPercent(1) element:parent():E("XpBar"):C("Sprite"):setColor(1, 1, 1) element:parent():E("XpBarBacking"):C("Sprite"):setColor(1, 1, 1)
element("ButtonState"):SetInt(game.BUTTON_RELEASED) element("TickTimer"):SetFloat(0.0) end

if game.popUpLevel() <= 1 and manager:isIdle() then if(element("disabledOnIsland"):GetInt() == 0) then element["icon"]:setColor(1.0, 1.0, 1.0) onTouchUp(component, element)
game.displayConfirmation("GOTO_BATTLE_ISLAND", game.battleButtonConf()) else game.displayNotification("BATTLE_ISLAND_HINT") end
element:parent():parent():Hide() end

template.event:
if(not game.inAdminViewMode()) then element:DoStoredScript("enable")
element["icon"]:setColor(1.0, 1.0, 1.0) element["Label"]:setColor(1.0, 1.0, 1.0)
element("disabledOnIsland"):SetInt(0) element:DoStoredScript("setVisibleOnIsland") element:DoStoredScript("show") end
